#!/usr/bin/env python3
# Derived from Azahar externals/open_source_archives/include/bad_word_list.app.romfs.h,
# externals/open_source_archives/include/country_list.app.romfs.h,
# externals/open_source_archives/include/mii.app.romfs.h and
# externals/open_source_archives/include/shared_font.app.romfs.h at 5f3306d13cab40bbd5cf38f2cf3ae8b6e6eedca6
# (the four headers carry no licence line: their Readme.md says they were generated by
# github.com/B3n30/citra_system_archives at commit 0baa5f5773432f04e3e671859780ded965c4248c, GPL-2.0-or-later;
# see PROVENANCE.md): the names of the four byte arrays and of their length variables
# (BAD_WORD_LIST_DATA, COUNTRY_LIST_DATA, MII_DATA, SHARED_FONT_DATA, each with a _len) and the `// Git Hash:`
# line, which this script reads from them.
# Copyright 2018/2019 Weiyi Wang (the citra_system_archives scripts that generated the headers; the headers
# themselves carry no Copyright line)
"""Turns Azahar's open-source system archive headers into compact binary files.

Azahar ships four replacement system archives as C byte arrays
(externals/open_source_archives/include/*.app.romfs.h, generated by
github.com/B3n30/citra_system_archives at commit 0baa5f5773432f04e3e671859780ded965c4248c).
This script reads those headers and writes the same bytes as plain binary files
(`data/<name>.dat`) plus `MANIFEST.txt` (sizes, CRC-32 and SHA-256 of every input and output).
The conversion is deterministic: running it again on the same headers gives the same files.

    make_archives.py AZAHAR_INCLUDE_DIR             write data/*.dat and MANIFEST.txt next to this script
    make_archives.py AZAHAR_INCLUDE_DIR --check     compare them with what the headers give (exit 1 if not)
    make_archives.py AZAHAR_INCLUDE_DIR --out DIR   write somewhere else

The archives are the open-source replacements, never anything read from a player's dump.
See PROVENANCE.md for where they come from and under which licences.
"""
from __future__ import annotations

import argparse
import hashlib
import re
import sys
import zlib
from dataclasses import dataclass
from pathlib import Path

HERE = Path(__file__).resolve().parent

# header file, array symbol, output name
ARCHIVES = (
    ("bad_word_list.app.romfs.h", "BAD_WORD_LIST_DATA", "bad_word_list"),
    ("country_list.app.romfs.h", "COUNTRY_LIST_DATA", "country_list"),
    ("mii.app.romfs.h", "MII_DATA", "mii"),
    ("shared_font.app.romfs.h", "SHARED_FONT_DATA", "shared_font"),
)


class ArchiveError(Exception):
    pass


@dataclass(frozen=True)
class Converted:
    name: str
    header: str
    header_sha256: str
    git_hash: str
    data: bytes


def parse_header(text: str, symbol: str) -> tuple[bytes, int]:
    """The bytes of `symbol[] = { 0x.., ... };` and the value of `symbol_len`."""
    body = re.search(r"\b" + re.escape(symbol) + r"\s*\[\s*\]\s*=\s*\{([^}]*)\}\s*;", text)
    if body is None:
        raise ArchiveError(f"no array {symbol}")
    tokens = [t.strip() for t in body.group(1).split(",")]
    values: list[int] = []
    for token in tokens:
        if not token:
            continue
        if not re.fullmatch(r"0[xX][0-9a-fA-F]{1,2}", token):
            raise ArchiveError(f"{symbol}: unexpected token {token!r}")
        values.append(int(token, 16))
    length = re.search(r"\b" + re.escape(symbol) + r"_len\s*=\s*(\d+)\s*;", text)
    if length is None:
        raise ArchiveError(f"no length {symbol}_len")
    return bytes(values), int(length.group(1))


def convert(include_dir: Path) -> list[Converted]:
    out: list[Converted] = []
    for header, symbol, name in ARCHIVES:
        path = include_dir / header
        try:
            raw = path.read_bytes()
        except OSError as e:
            raise ArchiveError(f"{path}: {e.strerror}") from e
        text = raw.decode("ascii")
        data, declared = parse_header(text, symbol)
        if len(data) != declared:
            raise ArchiveError(f"{header}: {len(data)} bytes in the array, {declared} declared")
        git = re.search(r"^// Git Hash: ([0-9a-f]{40})$", text, re.MULTILINE)
        out.append(Converted(name, header, hashlib.sha256(raw).hexdigest(),
                             git.group(1) if git else "unknown", data))
    return out


def manifest(items: list[Converted]) -> str:
    lines = [
        "# Generated by make_archives.py from Azahar's externals/open_source_archives/include.",
        "# name  size  crc32  sha256-of-the-.dat  azahar-header  sha256-of-the-header  citra_system_archives-git-hash",
    ]
    for item in items:
        lines.append(
            f"{item.name} {len(item.data)} {zlib.crc32(item.data):08x} "
            f"{hashlib.sha256(item.data).hexdigest()} {item.header} {item.header_sha256} {item.git_hash}")
    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n", 1)[0])
    parser.add_argument("include_dir", type=Path, help="Azahar's externals/open_source_archives/include")
    parser.add_argument("--out", type=Path, default=HERE, help="where data/ and MANIFEST.txt go (default: next to this script)")
    parser.add_argument("--check", action="store_true", help="write nothing; exit 1 if the files differ")
    args = parser.parse_args(argv)
    try:
        items = convert(args.include_dir)
    except ArchiveError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2
    expected = {f"data/{item.name}.dat": item.data for item in items}
    expected["MANIFEST.txt"] = manifest(items).encode("ascii")
    bad = 0
    for rel, content in expected.items():
        target = args.out / rel
        if args.check:
            if not target.is_file() or target.read_bytes() != content:
                print(f"differs: {rel}")
                bad += 1
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)
            print(f"wrote {rel} ({len(content)} bytes)")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
